(function(){function init(){const chat=document.getElementById('ariellaDesktopChat');if(!chat)return;const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages');if(!input||!send||!messages)return;let trolley=false,awaiting=false,confirmed=false;const value=k=>(chat.querySelector('[data-summary-key="'+k+'"] span')?.textContent||'').trim();function setBaggage(v){const el=chat.querySelector('[data-summary-key="baggage"] span');if(el){el.textContent=v;el.closest('.ac-detail')?.classList.add('is-filled')}}function summary(){return 'זה הסיכום לאישור:\n• יעד: '+value('destination')+'\n• תאריכים: '+value('dates')+'\n• נוסעים: '+value('travelers')+'\n• תקציב: '+value('budget')+'\n• טיסה: '+value('flight')+'\n• כבודה: '+(trolley?'טרולי / כבודה קטנה עד 8 ק״ג':value('baggage'))+'\n\nעברו בבקשה על הפרטים. אם הכול תקין כתבו "מאשר" או "כן". אם יש שינוי, כתבו לי מה לשנות.'}function finalToConfirm(){const bots=messages.querySelectorAll('.ac-row.bot .ac-bubble'),b=bots[bots.length-1];if(!b||confirmed)return;if(/יש לי את הפרטים הבסיסיים|continue to the search/i.test(b.textContent||'')){if(trolley)setBaggage('טרולי / כבודה קטנה עד 8 ק״ג');b.textContent=summary();awaiting=true;messages.scrollTop=messages.scrollHeight}}function add(who,text){const row=document.createElement('div');row.className='ac-row '+who;if(who==='bot'){const a=document.createElement('div');a.className='ac-mini-avatar';a.textContent='A';row.appendChild(a)}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;row.appendChild(b);messages.appendChild(row)}send.addEventListener('click',function(e){const raw=input.value.trim(),low=raw.toLowerCase();if(!raw)return;if(awaiting&&/^(כן|מאשר|מאשרת|אישור|yes|confirm)$/.test(low)){e.stopImmediatePropagation();input.value='';add('user',raw);add('bot','הפרטים אושרו ✓ אני מתחילה את החיפוש.');confirmed=true;awaiting=false;messages.scrollTop=messages.scrollHeight;return}if(awaiting)awaiting=false;if(/טרולי|כבודה קטנה|כבודת יד|תיק יד|8 קג|8 ק״ג|8 ק"ג/i.test(raw)){trolley=true;if(!/כבודה|מזוודה/i.test(raw))input.value=raw+' כבודה';setTimeout(()=>setBaggage('טרולי / כבודה קטנה עד 8 ק״ג'),260)}else if(/ללא כבודה|בלי כבודה|בלי מזוודה/i.test(raw))trolley=false;setTimeout(finalToConfirm,420)},true);input.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){const raw=input.value.trim();if(/טרולי|כבודה קטנה|כבודת יד|תיק יד|8 קג|8 ק״ג|8 ק"ג/i.test(raw)&&!/כבודה|מזוודה/i.test(raw)){trolley=true;input.value=raw+' כבודה';setTimeout(()=>setBaggage('טרולי / כבודה קטנה עד 8 ק״ג'),260);setTimeout(finalToConfirm,420)}}},true);new MutationObserver(()=>setTimeout(finalToConfirm,0)).observe(messages,{childList:true,subtree:true})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();